        // ===== 统一工厂（妙妙箱同款） =====
        public static Sprite CreatePixelSprite(Color[] pixels, int w, int h, float ppu)
        {
            // 10-07 实测修复：生成脚本按 PIL getdata（PNG 顶行在前）输出数组，而 Unity SetPixels 语义=底行在前
            //   （rows ordered from bottom to top）→ 直接 SetPixels 贴图上下颠倒。修正=按行翻转（Y 翻转）后再写。
            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);
            tex.filterMode = FilterMode.Point;
            tex.wrapMode = TextureWrapMode.Clamp;
            tex.hideFlags = HideFlags.DontSave;
            Color[] flipped = new Color[pixels.Length];
            for (int y = 0; y < h; y++)
                Array.Copy(pixels, (h - 1 - y) * w, flipped, y * w, w);
            tex.SetPixels(flipped);
            tex.Apply();
            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f), ppu);
            sprite.hideFlags = HideFlags.DontSave;
            return sprite;
        }

        // ===== 便捷方法（各物品 PPU 按替换前显示尺寸校准，10-07） =====
        public static Sprite GuMachineSprite() => CreatePixelSprite(GuMachine, 32, 32, 100f);
        public static Sprite AiGeneratorSprite() => CreatePixelSprite(AiGenerator, 32, 32, 100f);
        public static Sprite ProtectorCoreSprite() => CreatePixelSprite(ProtectorCore, 32, 32, 100f);
        public static Sprite DiceOfFateSprite() => CreatePixelSprite(DiceOfFate, 32, 32, 100f);
        public static Sprite VoidBeadSprite() => CreatePixelSprite(VoidBead, 32, 32, 100f);
        public static Sprite WageBrotherCardSprite() => CreatePixelSprite(WageBrotherCard, 32, 16, 100f);

        // 许可/充电器按文件名分发（WageBrother.GetPermitChargerSprite 懒加载用）
        public static Sprite PermitChargerSprite(string fileName)
        {
            switch (fileName)
            {
            case "wage_permit_1.png": return CreatePixelSprite(Permit1, 32, 32, 100f);
            case "wage_permit_2.png": return CreatePixelSprite(Permit2, 32, 32, 100f);
            case "wage_permit_3.png": return CreatePixelSprite(Permit3, 32, 32, 100f);
            case "wage_charger_1.png": return CreatePixelSprite(Charger1, 32, 32, 100f);
            case "wage_charger_2.png": return CreatePixelSprite(Charger2, 32, 32, 100f);
            case "wage_charger_3.png": return CreatePixelSprite(Charger3, 32, 32, 100f);
            }
            return null;
        }
    }
